Value.Calculation:
Let ( [
  ~y = GetAsNumber ( Left ( $rMonth ; 4 ) ) ;
  ~m = GetAsNumber ( Right ( $rMonth ; 2 ) ) ;
  ~y2 = If ( ~m = 12 ; ~y + 1 ; ~y ) ;
  ~m2 = If ( ~m = 12 ; 1 ; ~m + 1 ) ;
  ~pad = "00"
] ;
  ~y & "-" & Right ( ~pad & ~m ; 2 ) & "-01 00:00:00" & ¶ &
  ~y2 & "-" & Right ( ~pad & ~m2 ; 2 ) & "-01 00:00:00"
)

Let ( [
  ~ok = Left ( $raw ; 1 ) <> "?" and not IsEmpty ( $raw ) ;
  ~rows = Substitute ( Substitute ( $raw ; ¶ ; Char ( 11 ) ) ; Char ( 30 ) ; ¶ ) ;
  ~n = If ( ~ok ; ValueCount ( ~rows ) ; 0 )
] ;
While (
  [ ~i = 1 ; ~out = "[]" ] ;
  ~i <= ~n ;
  [
    ~r = Substitute ( GetValue ( ~rows ; ~i ) ; Char ( 31 ) ; ¶ ) ;
    ~p = "[" & ( ~i - 1 ) & "]" ;
    ~out = JSONSetElement ( ~out ;
      [ ~p & ".num" ; GetValue ( ~r ; 1 ) ; JSONString ] ;
      [ ~p & ".orderDate" ; GetValue ( ~r ; 2 ) ; JSONString ] ;
      [ ~p & ".created" ; GetValue ( ~r ; 3 ) ; JSONString ] ;
      [ ~p & ".name" ; Substitute ( GetValue ( ~r ; 4 ) ; Char ( 11 ) ; " " ) ; JSONString ] ;
      [ ~p & ".message" ; Substitute ( GetValue ( ~r ; 5 ) ; Char ( 11 ) ; ¶ ) ; JSONString ]
    ) ;
    ~i = ~i + 1
  ] ;
  ~out
) )

JSONSetElement ( "" ;
  [ "skip" ; $rSkip ; JSONNumber ] ;
  [ "top" ; $rTop ; JSONNumber ] ;
  [ "total" ; $rTotal ; JSONNumber ] ;
  [ "month" ; $rMonth ; JSONString ] ;
  [ "sqlError" ; Case ( Left ( $raw ; 1 ) = "?" ; "Could not read the orders for " & $rMonth & "." ; "" ) ; JSONString ]
)
